fwEvents.on("fw-builder:form-builder:register-items",function(a){fwFormBuilderSimpleItem(a,"rating",{preview:function(i){var e=fw.opg("scale",i)||"stars5";if(e==="stars5")return'<span class="fw-rating-preview fw-rating-preview--stars">\u2605\u2605\u2605\u2605\u2605</span>';for(var n=e==="nps"?0:1,s="",r=n;r<=10;r++)s+='<span class="fw-rating-preview__pill">'+r+"</span>";return'<span class="fw-rating-preview fw-rating-preview--pills">'+s+"</span>"}})});
